item.command:
/bin/bash -lc "mkdir -p verification/phase-5/evidence-r001
{
  echo 'command: environment and baseline inspection'
  echo 'started_at_utc: 2026-09-03T'"'$(date -u +%H:%M:%SZ)
  echo '"'commit:' "'$(git rev-parse HEAD)
  echo '"'git_status:'
  git status --short
  echo 'uname:' "'$(uname -srm)
  echo '"'python:' "'$(python3 --version 2>&1)
  echo '"'uv:' "'$(uv --version 2>&1)
  echo '"'node:' "'$(node --version 2>&1)
  echo '"'pnpm:' "'$(pnpm --version 2>&1)
  echo '"'postgres:' "'$(pg16 psql --version 2>&1)
  echo '"'docker:' "'$(docker --version 2>&1)
  echo '"'compose:' "'$(docker compose version 2>&1)
  echo '"'baseline_sha256:'
  sha256sum docs/baseline/agent-colab-project-spec_en-v8.md docs/baseline/agent-colab-development-plan_en-v8.md docs/baseline/agent-colab-validation-plan_en-v8.md docs/adr/ADR-0006-schedule-contract.md docs/adr/ADR-0012-phase5-schedule-decisions.md schemas/documents/verifier-report.v1.schema.json
  echo 'exit_code: 0'
} > verification/phase-5/evidence-r001/environment.txt
sed -n '1,240p' evidence/phase-5/manifest.yaml
rg -n \"P5-0|Phase 5|IMPLEMENTED\" PROGRESS.md docs/baseline/agent-colab-development-plan_en-v8.md | head -260
sed -n '150,335p' docs/baseline/agent-colab-project-spec_en-v8.md
sed -n '900,1100p' docs/baseline/agent-colab-development-plan_en-v8.md"

